(()=>{function add(){const a=document.querySelector('aside');if(!a||a.querySelector('[data-react-preview]'))return;const b=document.createElement('button');b.className='nav';b.dataset.reactPreview='1';b.innerHTML='⚛️ <span>Vista React (prueba)</span>';b.title='Abrir una vista experimental reconstruida con React';b.onclick=()=>location.href='./react-preview.html';const l=a.querySelector('.logout');l?a.insertBefore(b,l):a.appendChild(b)}add();new MutationObserver(add).observe(document.body,{childList:true,subtree:true})})();
